import { router } from 'expo-router';

type ChatRole = 'doctor' | 'patient';

// Consultation IDs are UUIDs generated by the API. Checking the value before
// navigating prevents Expo Router from opening a broken `/chat/undefined` URL
// when a screen has not received its consultation data yet.
const consultationIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isConsultationId(value: unknown): value is string {
  return typeof value === 'string' && consultationIdPattern.test(value);
}

export function openChat(conversationId: unknown, role: ChatRole) {
  if (!isConsultationId(conversationId)) {
    return false;
  }

  router.push({
    pathname: '/chat/[conversationId]',
    params: { conversationId, role },
  });
  return true;
}
